const optionEditorByTitle = async (
  page: Page,
  editorSelector: string,
  inputLabel: string,
  title: string,
  kind: string,
): Promise<Locator> => {
  const editors = page.locator(editorSelector);
  const inputs = editors.getByLabel(inputLabel, { exact: true });
  let matchingIndex = -1;

  await expect
    .poll(
      async () => {
        const inputValues = await inputs.evaluateAll((elements) =>
          elements.map((element) => {
            if (!(element instanceof HTMLInputElement)) {
              throw new Error('Expected a registration option input');
            }
            return element.value;
          }),
        );
        matchingIndex = inputValues.indexOf(title);
        return matchingIndex;
      },
      {
        message: `Expected ${kind} registration option "${title}"`,
        timeout: 15_000,
      },
    )
    .toBeGreaterThanOrEqual(0);

  return editors.nth(matchingIndex);
};

